// @ts-nocheck
// AUTO-GENERATED by Chart Studio. Edits here are overwritten on republish.
import type { ChartRenderFn } from "../renderers/genericChartRenderer";

export const renderBNVARouteMatrixD3: ChartRenderFn = (container, data, params, d3, containerWidth) => {
  container.innerHTML = "";
  // BNVA-style route ranking view.
  //
  // Expected data shape:
  //
  // {
  //   "Original Route": {
  //     "service cost": 2410,
  //     "passenger volume": 15400,
  //     "route length": 34,
  //     "number of stations": 42,
  //     "average load": 3.8,
  //     directness: 1.24
  //   },
  //   "Alternative A": {
  //     ...
  //   }
  // }
  //
  // Each top-level key is an alternative scenario.
  //
  // Rows    = route alternatives
  // Columns = performance criteria
  //
  // Header distribution = distribution of alternatives
  // Dashed line         = baseline/original-route value
  // Cell bar            = criterion magnitude
  // Cell text           = exact value


  const scenarioKeys = Object.keys(data);

  if (scenarioKeys.length === 0) return;

  const props = params ?? {};


  // ============================================================
  // PROPS / LAYOUT
  // ============================================================

  const baselineKey =
    props.baselineKey ??
    "Original Route";

  const rowHeight =
    props.rowHeight ??
    42;

  const headerHeight =
    props.headerHeight ??
    105;

  const titleHeight =
    props.titleHeight ??
    42;

  const labelColWidth =
    props.labelColWidth ??
    145;

  const requestedColWidth =
    props.colWidth;

  const histogramBins =
    props.histogramBins ??
    7;

  const showValues =
    props.showValues ??
    true;

  const showBaselineRow =
    props.showBaselineRow ??
    false;

  const showBaselineMarkers =
    props.showBaselineMarkers ??
    true;

  const showBaselineLegend =
    props.showBaselineLegend ??
    true;

  const showGrid =
    props.showGrid ??
    true;

  const barHeight =
    props.barHeight ??
    16;

  const barMaxRatio =
    props.barMaxRatio ??
    0.78;

  const cellPaddingX =
    props.cellPaddingX ??
    10;


  // ============================================================
  // TEXT
  // ============================================================

  const title =
    props.title ??
    "Alternative Route Comparison";

  const scenarioLabel =
    props.scenarioLabel ??
    "Route Candidate";


  // ============================================================
  // COLORS
  // ============================================================

  const barColor =
    props.barColor ??
    "#6b9ac4";

  const histogramColor =
    props.histogramColor ??
    "#cbd5e1";

  const histogramStroke =
    props.histogramStroke ??
    "#64748b";

  const baselineColor =
    props.baselineColor ??
    "#374151";

  const baselineRowColor =
    props.baselineRowColor ??
    "#f3f4f6";

  const hoverColor =
    props.hoverColor ??
    "#f8fafc";

  const gridColor =
    props.gridColor ??
    "#e5e7eb";

  const textColor =
    props.textColor ??
    "#374151";

  const mutedTextColor =
    props.mutedTextColor ??
    "#6b7280";


  // ============================================================
  // FORMATTING
  // ============================================================

  const currencySymbol =
    props.currencySymbol ??
    "$";

  const metricLabels =
    props.metricLabels ?? {};

  const metricFormats =
    props.metricFormats ?? {};


  function prettyLabel(key) {
    if (metricLabels[key]) {
      return metricLabels[key];
    }

    return String(key)
      .replace(/_/g, " ")
      .replace(
        /\b\w/g,
        (c) => c.toUpperCase()
      );
  }


  function formatValue(
    key,
    value
  ) {
    if (
      value == null ||
      !Number.isFinite(value)
    ) {
      return "—";
    }

    const format =
      metricFormats[key];

    if (format === "currency") {
      return (
        currencySymbol +
        d3.format(",.0f")(value)
      );
    }

    if (
      format ===
      "currencyCompact"
    ) {
      return (
        currencySymbol +
        d3.format(".3~s")(value)
      );
    }

    if (format === "integer") {
      return d3.format(",.0f")(
        value
      );
    }

    if (format === "oneDecimal") {
      return d3.format(".1f")(
        value
      );
    }

    if (format === "twoDecimal") {
      return d3.format(".2f")(
        value
      );
    }

    if (
      format ===
      "threeDecimal"
    ) {
      return d3.format(".3f")(
        value
      );
    }

    if (format === "km") {
      return (
        d3.format(".0f")(value) +
        " km"
      );
    }

    return d3.format(
      ",.3~f"
    )(value);
  }


  // ============================================================
  // DETERMINE METRICS
  // ============================================================

  let metricKeys =
    props.metricOrder;

  if (
    !Array.isArray(metricKeys) ||
    metricKeys.length === 0
  ) {
    metricKeys = [];

    const seen =
      new Set();

    scenarioKeys.forEach(
      (scenario) => {
        const values =
          data[scenario] ?? {};

        Object.keys(
          values
        ).forEach(
          (key) => {
            if (
              Number.isFinite(
                values[key]
              ) &&
              !seen.has(key)
            ) {
              seen.add(key);
              metricKeys.push(key);
            }
          }
        );
      }
    );
  }


  // ============================================================
  // BASELINE / CANDIDATES
  // ============================================================

  const baseline =
    data[baselineKey];

  const candidateKeys =
    scenarioKeys.filter(
      (key) =>
        key !== baselineKey
    );


  // ============================================================
  // VISIBLE ROWS
  // ============================================================

  let visibleKeys =
    showBaselineRow
      ? [...scenarioKeys]
      : [...candidateKeys];


  // ============================================================
  // SVG SIZE
  // ============================================================

  const width =
    containerWidth ||
    900;

  const availablePlotWidth =
    Math.max(
      width -
        labelColWidth -
        16,
      200
    );

  const colWidth =
    requestedColWidth ??
    availablePlotWidth /
      Math.max(
        metricKeys.length,
        1
      );

  const tableTop =
    titleHeight +
    headerHeight;

  const height =
    tableTop +
    visibleKeys.length *
      rowHeight +
    20;

  const svgWidth =
    Math.max(
      width,
      labelColWidth +
        metricKeys.length *
          colWidth +
        16
    );


  // ============================================================
  // CREATE SVG
  // ============================================================

  const svg = d3
    .select(container)
    .append("svg")
    .attr(
      "width",
      svgWidth
    )
    .attr(
      "height",
      height
    )
    .attr(
      "viewBox",
      `0 0 ${svgWidth} ${height}`
    )
    .style(
      "font-family",
      "Inter, sans-serif"
    );


  // ============================================================
  // TITLE
  // ============================================================

  svg
    .append("text")
    .attr("x", 8)
    .attr("y", 17)
    .style(
      "font-size",
      "15px"
    )
    .style(
      "font-weight",
      700
    )
    .attr(
      "fill",
      textColor
    )
    .text(title);


  svg
    .append("text")
    .attr("x", 8)
    .attr("y", 33)
    .style(
      "font-size",
      "10.5px"
    )
    .attr(
      "fill",
      mutedTextColor
    )
    .text(
      `${candidateKeys.length} alternative${
        candidateKeys.length === 1
          ? ""
          : "s"
      }${
        baseline
          ? ` compared with ${baselineKey}`
          : ""
      }`
    );


  // ============================================================
  // BASELINE LEGEND
  // ============================================================

  if (
    baseline &&
    showBaselineMarkers &&
    showBaselineLegend
  ) {
    const legendX =
      Math.max(
        labelColWidth,
        labelColWidth +
          metricKeys.length *
            colWidth -
          125
      );

    svg
      .append("line")
      .attr(
        "x1",
        legendX
      )
      .attr(
        "x2",
        legendX + 22
      )
      .attr(
        "y1",
        18
      )
      .attr(
        "y2",
        18
      )
      .attr(
        "stroke",
        baselineColor
      )
      .attr(
        "stroke-width",
        1.4
      )
      .attr(
        "stroke-dasharray",
        "4,3"
      );

    svg
      .append("text")
      .attr(
        "x",
        legendX + 28
      )
      .attr(
        "y",
        21
      )
      .style(
        "font-size",
        "9.5px"
      )
      .attr(
        "fill",
        mutedTextColor
      )
      .text(
        baselineKey
      );
  }


  // ============================================================
  // METRIC SCALES
  // ============================================================

  const metricScales = {};
  const histogramScales = {};


  metricKeys.forEach(
    (metric) => {

      const allValues =
        scenarioKeys
          .map(
            (scenario) =>
              data[
                scenario
              ]?.[
                metric
              ]
          )
          .filter(
            Number.isFinite
          );


      let minValue =
        d3.min(
          allValues
        ) ?? 0;

      let maxValue =
        d3.max(
          allValues
        ) ?? 1;


      if (
        minValue === maxValue
      ) {
        maxValue =
          minValue + 1;
      }


      // Cell bars.
      //
      // All BNVA criteria in the example are positive,
      // so bars begin at zero.
      metricScales[
        metric
      ] =
        d3
          .scaleLinear()
          .domain([
            0,
            Math.max(
              maxValue,
              1
            )
          ])
          .range([
            0,
            Math.max(
              (
                colWidth -
                cellPaddingX * 2
              ) *
                barMaxRatio,
              1
            )
          ]);


      // Header distribution scale.
      const padding =
        Math.max(
          (
            maxValue -
            minValue
          ) *
            0.08,
          0.0001
        );


      histogramScales[
        metric
      ] =
        d3
          .scaleLinear()
          .domain([
            minValue -
              padding,
            maxValue +
              padding
          ])
          .range([
            12,
            colWidth - 12
          ]);
    }
  );


  // ============================================================
  // FIRST COLUMN LABEL
  // ============================================================

  svg
    .append("text")
    .attr(
      "x",
      labelColWidth -
        12
    )
    .attr(
      "y",
      tableTop - 9
    )
    .attr(
      "text-anchor",
      "end"
    )
    .style(
      "font-size",
      "10.5px"
    )
    .style(
      "font-weight",
      600
    )
    .attr(
      "fill",
      mutedTextColor
    )
    .text(
      scenarioLabel
    );


  // ============================================================
  // HEADER DISTRIBUTIONS
  // ============================================================

  metricKeys.forEach(
    (
      metric,
      metricIndex
    ) => {

      const columnX =
        labelColWidth +
        metricIndex *
          colWidth;

      const headerG =
        svg
          .append("g")
          .attr(
            "transform",
            `translate(${columnX}, ${titleHeight})`
          );


      // --------------------------------------------------------
      // Metric name
      // --------------------------------------------------------

      headerG
        .append("text")
        .attr(
          "x",
          colWidth / 2
        )
        .attr(
          "y",
          12
        )
        .attr(
          "text-anchor",
          "middle"
        )
        .style(
          "font-size",
          "10.5px"
        )
        .style(
          "font-weight",
          700
        )
        .attr(
          "fill",
          textColor
        )
        .text(
          prettyLabel(
            metric
          )
        );


      // --------------------------------------------------------
      // Candidate distribution
      //
      // Baseline is NOT included.
      // --------------------------------------------------------

      const candidateValues =
        candidateKeys
          .map(
            (scenario) =>
              data[
                scenario
              ]?.[
                metric
              ]
          )
          .filter(
            Number.isFinite
          );


      const xScale =
        histogramScales[
          metric
        ];

      const histogramTop =
        28;

      const histogramBottom =
        headerHeight -
        18;


      if (
        candidateValues.length >
        0
      ) {

        const binGenerator =
          d3
            .bin()
            .domain(
              xScale.domain()
            )
            .thresholds(
              histogramBins
            );


        const bins =
          binGenerator(
            candidateValues
          );


        const maxCount =
          d3.max(
            bins,
            (d) =>
              d.length
          ) || 1;


        const yScale =
          d3
            .scaleLinear()
            .domain([
              0,
              maxCount
            ])
            .range([
              histogramBottom,
              histogramTop
            ]);


        const area =
          d3
            .area()
            .x(
              (d) =>
                xScale(
                  (
                    d.x0 +
                    d.x1
                  ) /
                    2
                )
            )
            .y0(
              histogramBottom
            )
            .y1(
              (d) =>
                yScale(
                  d.length
                )
            )
            .curve(
              d3
                .curveMonotoneX
            );


        headerG
          .append("path")
          .datum(
            bins
          )
          .attr(
            "d",
            area
          )
          .attr(
            "fill",
            histogramColor
          )
          .attr(
            "fill-opacity",
            0.8
          )
          .attr(
            "stroke",
            histogramStroke
          )
          .attr(
            "stroke-width",
            1
          );


        headerG
          .append("line")
          .attr(
            "x1",
            10
          )
          .attr(
            "x2",
            colWidth - 10
          )
          .attr(
            "y1",
            histogramBottom
          )
          .attr(
            "y2",
            histogramBottom
          )
          .attr(
            "stroke",
            gridColor
          );
      }


      // --------------------------------------------------------
      // Baseline/original-route marker
      // --------------------------------------------------------

      const baselineValue =
        baseline?.[
          metric
        ];


      if (
        showBaselineMarkers &&
        Number.isFinite(
          baselineValue
        )
      ) {

        const baselineX =
          xScale(
            baselineValue
          );


        headerG
          .append("line")
          .attr(
            "x1",
            baselineX
          )
          .attr(
            "x2",
            baselineX
          )
          .attr(
            "y1",
            histogramTop - 2
          )
          .attr(
            "y2",
            histogramBottom + 4
          )
          .attr(
            "stroke",
            baselineColor
          )
          .attr(
            "stroke-width",
            1.4
          )
          .attr(
            "stroke-dasharray",
            "4,3"
          );


        headerG
          .append("circle")
          .attr(
            "cx",
            baselineX
          )
          .attr(
            "cy",
            histogramBottom +
              4
          )
          .attr(
            "r",
            2.4
          )
          .attr(
            "fill",
            baselineColor
          )
          .append("title")
          .text(
            `${baselineKey}\n` +
            `${prettyLabel(
              metric
            )}: ${formatValue(
              metric,
              baselineValue
            )}`
          );
      }


      // --------------------------------------------------------
      // Column divider
      // --------------------------------------------------------

      if (showGrid) {
        headerG
          .append("line")
          .attr(
            "x1",
            0
          )
          .attr(
            "x2",
            0
          )
          .attr(
            "y1",
            0
          )
          .attr(
            "y2",
            headerHeight +
              visibleKeys.length *
                rowHeight
          )
          .attr(
            "stroke",
            gridColor
          );
      }
    }
  );


  // ============================================================
  // TABLE TOP BORDER
  // ============================================================

  if (showGrid) {
    svg
      .append("line")
      .attr(
        "x1",
        0
      )
      .attr(
        "x2",
        labelColWidth +
          metricKeys.length *
            colWidth
      )
      .attr(
        "y1",
        tableTop
      )
      .attr(
        "y2",
        tableTop
      )
      .attr(
        "stroke",
        "#cbd5e1"
      );
  }


  // ============================================================
  // ROWS
  // ============================================================

  visibleKeys.forEach(
    (
      scenario,
      rowIndex
    ) => {

      const values =
        data[scenario] ?? {};

      const rowY =
        tableTop +
        rowIndex *
          rowHeight;

      const isBaseline =
        scenario ===
        baselineKey;


      // --------------------------------------------------------
      // Row background
      // --------------------------------------------------------

      const rowBackground =
        svg
          .append("rect")
          .attr(
            "x",
            0
          )
          .attr(
            "y",
            rowY
          )
          .attr(
            "width",
            labelColWidth +
              metricKeys.length *
                colWidth
          )
          .attr(
            "height",
            rowHeight
          )
          .attr(
            "fill",
            isBaseline
              ? baselineRowColor
              : "#ffffff"
          );


      if (!isBaseline) {
        rowBackground
          .on(
            "mouseenter",
            function () {
              d3
                .select(this)
                .attr(
                  "fill",
                  hoverColor
                );
            }
          )
          .on(
            "mouseleave",
            function () {
              d3
                .select(this)
                .attr(
                  "fill",
                  "#ffffff"
                );
            }
          );
      }


      // --------------------------------------------------------
      // Scenario name
      // --------------------------------------------------------

      svg
        .append("text")
        .attr(
          "x",
          labelColWidth -
            12
        )
        .attr(
          "y",
          rowY +
            rowHeight / 2 +
            4
        )
        .attr(
          "text-anchor",
          "end"
        )
        .style(
          "font-size",
          "11px"
        )
        .style(
          "font-weight",
          isBaseline
            ? 700
            : 500
        )
        .attr(
          "fill",
          isBaseline
            ? baselineColor
            : textColor
        )
        .text(
          scenario
        );


      // ========================================================
      // CELLS
      // ========================================================

      metricKeys.forEach(
        (
          metric,
          metricIndex
        ) => {

          const value =
            values[
              metric
            ];

          const cellX =
            labelColWidth +
            metricIndex *
              colWidth;


          // ----------------------------------------------------
          // Missing value
          // ----------------------------------------------------

          if (
            !Number.isFinite(
              value
            )
          ) {

            svg
              .append("text")
              .attr(
                "x",
                cellX +
                  colWidth / 2
              )
              .attr(
                "y",
                rowY +
                  rowHeight / 2 +
                  4
              )
              .attr(
                "text-anchor",
                "middle"
              )
              .style(
                "font-size",
                "10px"
              )
              .attr(
                "fill",
                "#9ca3af"
              )
              .text("—");

            return;
          }


          // ----------------------------------------------------
          // Bar geometry
          // ----------------------------------------------------

          const scale =
            metricScales[
              metric
            ];

          const barW =
            Math.max(
              scale(
                value
              ),
              1
            );

          const barY =
            rowY +
            (
              rowHeight -
              barHeight
            ) /
              2;


          // ----------------------------------------------------
          // Value bar
          // ----------------------------------------------------

          svg
            .append("rect")
            .attr(
              "x",
              cellX +
                cellPaddingX
            )
            .attr(
              "y",
              barY
            )
            .attr(
              "width",
              barW
            )
            .attr(
              "height",
              barHeight
            )
            .attr(
              "rx",
              1.5
            )
            .attr(
              "fill",
              isBaseline
                ? baselineColor
                : barColor
            )
            .attr(
              "fill-opacity",
              isBaseline
                ? 0.35
                : 0.72
            );


          // ----------------------------------------------------
          // Numeric value
          // ----------------------------------------------------

          if (showValues) {

            svg
              .append("text")
              .attr(
                "x",
                cellX +
                  cellPaddingX +
                  3
              )
              .attr(
                "y",
                rowY +
                  rowHeight / 2 +
                  3.5
              )
              .style(
                "font-size",
                "9.5px"
              )
              .style(
                "font-weight",
                600
              )
              .attr(
                "fill",
                "#1f2937"
              )
              .text(
                formatValue(
                  metric,
                  value
                )
              );
          }


          // ----------------------------------------------------
          // Tooltip
          // ----------------------------------------------------

          let tooltip =
            `${scenario}\n` +
            `${prettyLabel(
              metric
            )}: ${formatValue(
              metric,
              value
            )}`;


          const baselineValue =
            baseline?.[
              metric
            ];


          if (
            !isBaseline &&
            Number.isFinite(
              baselineValue
            )
          ) {

            const difference =
              value -
              baselineValue;

            const percentage =
              baselineValue !==
              0
                ? (
                    difference /
                    baselineValue
                  ) *
                  100
                : null;


            tooltip +=
              `\n${baselineKey}: ${formatValue(
                metric,
                baselineValue
              )}`;


            tooltip +=
              `\nDifference: ${
                difference > 0
                  ? "+"
                  : ""
              }${d3.format(
                ",.3~f"
              )(difference)}`;


            if (
              percentage !=
              null
            ) {
              tooltip +=
                ` (${
                  percentage > 0
                    ? "+"
                    : ""
                }${percentage.toFixed(
                  1
                )}%)`;
            }
          }


          svg
            .append("rect")
            .attr(
              "x",
              cellX
            )
            .attr(
              "y",
              rowY
            )
            .attr(
              "width",
              colWidth
            )
            .attr(
              "height",
              rowHeight
            )
            .attr(
              "fill",
              "transparent"
            )
            .append("title")
            .text(
              tooltip
            );
        }
      );


      // --------------------------------------------------------
      // Row separator
      // --------------------------------------------------------

      if (showGrid) {
        svg
          .append("line")
          .attr(
            "x1",
            0
          )
          .attr(
            "x2",
            labelColWidth +
              metricKeys.length *
                colWidth
          )
          .attr(
            "y1",
            rowY +
              rowHeight
          )
          .attr(
            "y2",
            rowY +
              rowHeight
          )
          .attr(
            "stroke",
            gridColor
          );
      }
    }
  );


  // ============================================================
  // RIGHT BORDER
  // ============================================================

  if (showGrid) {

    const rightX =
      labelColWidth +
      metricKeys.length *
        colWidth;

    svg
      .append("line")
      .attr(
        "x1",
        rightX
      )
      .attr(
        "x2",
        rightX
      )
      .attr(
        "y1",
        titleHeight
      )
      .attr(
        "y2",
        tableTop +
          visibleKeys.length *
            rowHeight
      )
      .attr(
        "stroke",
        gridColor
      );
  }
};
